changeSet.sql:
ALTER TABLE collection
	ADD CONSTRAINT ck_collection_release_status
	CHECK (release_status IN ('DRAFT', 'READY_FOR_REVIEW', 'CHANGES_REQUESTED',
		'APPROVED', 'PUBLISHED', 'RETIRED'));
ALTER TABLE collectible_template
	ADD CONSTRAINT ck_template_publish_status
	CHECK (publish_status IN ('DRAFT', 'READY_FOR_REVIEW', 'CHANGES_REQUESTED',
		'APPROVED', 'PUBLISHED', 'RETIRED'));
ALTER TABLE collectible_template
	ADD CONSTRAINT ck_template_edition_size_positive CHECK (edition_size > 0);
